reference_solution.solution.c:
#include "ring.h"
void ring_init(Ring *r){r->head=r->tail=r->count=0;}
int ring_push(Ring *r,uint8_t v){if(r->count==4)return 0;r->data[r->head]=v;r->head=(r->head+1)%4;r->count++;return 1;}
int ring_pop(Ring *r,uint8_t *out){if(!r->count)return 0;*out=r->data[r->tail];r->tail=(r->tail+1)%4;r->count--;return 1;}
